import { useDispatch, useSelector } from "react-redux";
import { getTodaysWeather } from "../../store/weatherSlice/weatherSlice";
import { useEffect } from "react";
import { fetchTodaysWeather } from "../../store/weatherSlice/api";

const TodaysWeather = ({ city }) => {
  const dispatch = useDispatch();
  const data = useSelector(getTodaysWeather);
  useEffect(() => {
    dispatch(fetchTodaysWeather(city));
  }, [city]);
  return (
    <div>
      {data && 
      <div>
        <h1>{data.name}</h1>
        <p>{data.weather[0].icon}</p>
        {/* <img src={data.weather[0].icon} alt="" /> */}
      </div>
      }
    </div>
  );
};

export default TodaysWeather;
